/**
 * A single appointment within one day.
 * Appointments are ordered by START TIME ONLY. This is intentional:
 * the scheduler allows at most one appointment to start at a given minute.
 *
 * Provided class: students do not edit this file.
 */
public final class Appointment implements Comparable<Appointment> {
    private final int startMinutes;
    private final int durationMinutes;
    private final String title;

    public Appointment(int startMinutes, int durationMinutes, String title) {
        if (startMinutes < 0 || startMinutes >= 24 * 60) {
            throw new IllegalArgumentException("Start time must be within the day.");
        }
        if (durationMinutes <= 0 || startMinutes + durationMinutes > 24 * 60) {
            throw new IllegalArgumentException("Duration must be positive and end within the day.");
        }
        if (title == null || title.isBlank() || title.contains("|") ||
                title.contains("\n") || title.contains("\r")) {
            throw new IllegalArgumentException("Title cannot be blank or contain |.");
        }
        this.startMinutes = startMinutes;
        this.durationMinutes = durationMinutes;
        this.title = title.trim();
    }

    public int getStartMinutes() { return startMinutes; }
    public int getDurationMinutes() { return durationMinutes; }
    public int getEndMinutes() { return startMinutes + durationMinutes; }
    public String getTitle() { return title; }

    @Override
    public int compareTo(Appointment other) {
        return Integer.compare(this.startMinutes, other.startMinutes);
    }

    /** A temporary search key; TreeSet compares only the start time. */
    public static Appointment keyAt(int startMinutes) {
        return new Appointment(startMinutes, 1, "(search key)");
    }

    /** Accepts time in H:MM or HH:MM, using 24-hour time. */
    public static int parseTime(String text) {
        String[] parts = text.trim().split(":", -1);
        if (parts.length != 2) throw new IllegalArgumentException("Use HH:MM time.");
        try {
            int h = Integer.parseInt(parts[0]);
            int m = Integer.parseInt(parts[1]);
            if (h < 0 || h > 23 || m < 0 || m > 59) {
                throw new IllegalArgumentException("Time is outside the 24-hour clock.");
            }
            return 60 * h + m;
        } catch (NumberFormatException ex) {
            throw new IllegalArgumentException("Use HH:MM time.");
        }
    }

    public static String formatTime(int minutes) {
        return String.format("%02d:%02d", minutes / 60, minutes % 60);
    }

    /** On-disk format: HH:MM|duration_minutes|title */
    public String toFileLine() {
        return formatTime(startMinutes) + "|" + durationMinutes + "|" + title;
    }

    public static Appointment fromFileLine(String line) {
        String[] parts = line.split("\\|", 3);
        if (parts.length != 3) throw new IllegalArgumentException("Invalid appointment line: " + line);
        try {
            return new Appointment(parseTime(parts[0]), Integer.parseInt(parts[1].trim()), parts[2]);
        } catch (NumberFormatException ex) {
            throw new IllegalArgumentException("Invalid duration: " + line);
        }
    }

    @Override
    public String toString() {
        return formatTime(startMinutes) + "-" + formatTime(getEndMinutes()) + "  " + title;
    }
}
